#!/usr/bin/env python3
"""Round 56 (26 September): Selected Layers; Base and reference and Buildings out; switches for every point, shape or national layer at once. Upload to the culprits repo's patches folder. Safe to run twice."""
import base64, subprocess, sys, os, tempfile
DIFF = base64.b64decode("")
NOTE = """
## Round 56 (26 September)

- "Selected Layers" h1 above Off-planet invasion, empty until the owner names
  its layers. Base and reference and Buildings headings taken out;
  building_types in PANEL_REMOVED.
- Kind switches under the layer search ("Turn on every": Points, Shapes,
  National highlights; any together): layerKind(cfg) from route and unit,
  catalogueKind(cfg, item) for catalogue rows (data-kind on their inputs; GFW
  from its asset). Catalogue rows included at the owner's word; ticked 8 at a
  time every 150 ms.
- GFW's download/gpkg answers 403 without an API key, so gfw_copies.py is
  deleted from culprits-tiles-more (round 56 tiles patch) and the three copy_*
  rows are gone; GFW's own rows for those datasets stay.
"""
def git(*a):
    return subprocess.run(["git", *a], capture_output=True, text=True)
if not os.path.exists("map/app.js"):
    sys.exit("Run this from the culprits folder.")
with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
    f.write(DIFF); path = f.name
if git("apply", "--check", "-R", path).returncode == 0:
    print("Already applied. Nothing changed.")
else:
    r = git("apply", "--3way", path)
    if r.returncode != 0:
        print(r.stdout + r.stderr)
        git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html")
        sys.exit("Did not apply; nothing changed.")
    print("Code changes applied.")
os.unlink(path)
if os.path.exists("HANDOFF.md"):
    h = open("HANDOFF.md", encoding="utf-8").read()
    if "## Round 56 (26 September)" not in h:
        i = h.index("---") + 3
        open("HANDOFF.md", "w", encoding="utf-8").write(h[:i] + "\n" + NOTE + h[i:])
        print("HANDOFF.md note added.")
